@[simp] theorem mem_tangentSpace_iff {p : ι → C} {F : DifferentialPolynomial ι C}
    {s : Finset (ι × ℕ)} {X : ι → C} :
    X ∈ tangentSpace p F s ↔ linearisationForm p F s X = 0

