theorem chronologicalMobiusWeightedSource_mellin (w : ℝ → ℂ) {s : ℂ}
    (hs : 1 < s.re) (hw : MellinConvergent w s) :
    mellin (chronologicalMobiusWeightedSource w) s = mellin w s * (riemannZeta s)⁻¹

theorem continuous_mellin_line {f : ℝ → ℂ} {sigma : ℝ}
    (hf1 : Integrable (logMellinLineSource f sigma)) :
    Continuous (fun t : ℝ => mellin f ((sigma : ℂ) + (t : ℂ) * I))

theorem mellinConvergent_source {f : ℝ → ℝ} (hm : Measurable f) {B L : ℝ}
    (hbnd : ∀ x, |f x| ≤ B) (hsupp : ∀ x, x ∉ Ioc (0 : ℝ) L → f x = 0) {s : ℂ} (hs : 0 < s.re) :
    IntegrableOn (fun t : ℝ => (t : ℂ) ^ (s - 1) • ((f t : ℝ) : ℂ)) (Ioi 0)

theorem chronologicalMobiusWeightedSource_hasMellin (w : ℝ → ℂ) {s : ℂ}
    (hs : 1 < s.re) (hw : MellinConvergent w s) :
    HasMellin (chronologicalMobiusWeightedSource w) s (mellin w s * (riemannZeta s)⁻¹)

